import requests
u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi'
terms=['(naked plasmid OR naked DNA) skeletal muscle diabetes','intramuscular plasmid insulin diabetic rats gene transfer','skeletal muscle gene transfer diabetes plasmid']
for t in terms:
 r=requests.get(u,params={'db':'pubmed','term':t,'retmax':20,'retmode':'json'},timeout=20); r.raise_for_status(); d=r.json()['esearchresult']; print('\nQUERY:',t,'COUNT',d['count'],'IDS',d['idlist'])
 ids=','.join(d['idlist'])
 if ids:
  x=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':ids,'retmode':'json'},timeout=20).json()['result']
  for i in d['idlist']:
   q=x[i]; print(i,q.get('pubdate'),q.get('title'))
